fix.code:
@Bean
RestClient pricingClient(RestClient.Builder builder) {
    // Little's law: 300 req/s cao điểm × p99 150ms ≈ 45 kết nối đồng thời, dư thành 50
    PoolingHttpClientConnectionManager pool = PoolingHttpClientConnectionManagerBuilder.create()
            .setMaxConnPerRoute(50)
            .setMaxConnTotal(100)
            .setDefaultConnectionConfig(ConnectionConfig.custom()
                    .setConnectTimeout(Timeout.ofMilliseconds(500))
                    .setSocketTimeout(Timeout.ofSeconds(1))
                    .setTimeToLive(TimeValue.ofMinutes(5))
                    .build())
            .build();

    CloseableHttpClient http = HttpClients.custom()
            .setConnectionManager(pool)
            .setDefaultRequestConfig(RequestConfig.custom()
                    .setConnectionRequestTimeout(Timeout.ofMilliseconds(200))  // chờ pool tối đa 200ms
                    .setResponseTimeout(Timeout.ofSeconds(1))
                    .build())
            .evictIdleConnections(TimeValue.ofSeconds(30))  // ngắn hơn keep-alive của server
            .build();

    return builder.baseUrl("http://pricing-service")
            .requestFactory(new HttpComponentsClientHttpRequestFactory(http))
            .build();
}
